<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { Archive, Clock3, Edit3, Eye, MessageSquarePlus, Megaphone, Send, Trash2, X } from '@lucide/vue'
import { createAdminAnnouncement, deleteAdminAnnouncement, getAdminAnnouncementReadStatus, listAdminAnnouncements, updateAdminAnnouncement } from '@/api/admin/announcements'
import type { AdminAnnouncement, AdminAnnouncementReadStatus, AdminAnnouncementStatus } from '@/api/admin/types'
import { formatCost, formatDateTime } from '@/lib/format'
import { toast } from '@/stores/toast'

const items=ref<AdminAnnouncement[]>([]),total=ref(0),loading=ref(true),loadError=ref(''),editorOpen=ref(false),editing=ref<AdminAnnouncement|null>(null),readOpen=ref<AdminAnnouncement|null>(null),readRows=ref<AdminAnnouncementReadStatus[]>([]),editorError=ref(''),statusFilter=ref(''),pending=ref('')
const form=reactive({title:'',content:'',status:'draft' as AdminAnnouncementStatus,notifyMode:'silent'as'silent'|'popup',targetType:'all'as'all'|'balance'|'subscription',balanceValue:0,groupIds:''})
function errorMessage(caught:unknown,fallback:string){return caught instanceof Error&&caught.message?caught.message:fallback}
async function load(){loading.value=true;loadError.value='';try{const result=await listAdminAnnouncements({page:1,page_size:20,status:statusFilter.value||undefined});items.value=result.items;total.value=result.total}catch(caught){loadError.value=errorMessage(caught,'公告列表加载失败')}finally{loading.value=false}}
function openCreate(){editing.value=null;editorError.value='';editorOpen.value=true}function openEdit(item:AdminAnnouncement){editing.value=item;editorError.value='';editorOpen.value=true}
watch(editorOpen,open=>{if(!open)return;form.title=editing.value?.title??'';form.content=editing.value?.content??'';form.status=editing.value?.status??'draft';form.notifyMode=editing.value?.notify_mode??'silent';form.targetType='all';form.balanceValue=0;form.groupIds=''})
function targeting(){if(form.targetType==='balance')return{any_of:[{all_of:[{type:'balance'as const,operator:'gte'as const,value:Number(form.balanceValue)||0}]}]};if(form.targetType==='subscription')return{any_of:[{all_of:[{type:'subscription'as const,operator:'in'as const,group_ids:form.groupIds.split(',').map(Number).filter(Boolean)}]}]};return{}}
async function save(){const payload={title:form.title.trim(),content:form.content.trim(),status:form.status,notify_mode:form.notifyMode,targeting:targeting()};editorError.value='';if(!payload.title||!payload.content){editorError.value='请填写公告标题和内容';return}pending.value='save';try{const saved=editing.value?await updateAdminAnnouncement(editing.value.id,payload):await createAdminAnnouncement(payload);const index=items.value.findIndex(item=>item.id===saved.id);if(index>=0)items.value[index]=saved;else items.value.unshift(saved);editorOpen.value=false;toast.success('公告已保存')}catch(caught){editorError.value=errorMessage(caught,'公告保存失败');toast.error('公告保存失败',{detail:editorError.value})}finally{pending.value=''}}
async function setStatus(item:AdminAnnouncement,status:AdminAnnouncementStatus){pending.value=`status-${item.id}`;try{const updated=await updateAdminAnnouncement(item.id,{status});items.value=items.value.map(current=>current.id===item.id?updated:current);toast.success(status==='active'?'公告已发布':'公告已归档')}catch(caught){toast.error('公告状态更新失败',{detail:errorMessage(caught,'请稍后重试。')})}finally{pending.value=''}}
async function remove(item:AdminAnnouncement){if(!window.confirm(`确认删除公告“${item.title}”？`))return;pending.value=`delete-${item.id}`;try{await deleteAdminAnnouncement(item.id);toast.success('公告已删除');await load()}catch(caught){toast.error('公告删除失败',{detail:errorMessage(caught,'请稍后重试。')})}finally{pending.value=''}}
async function openRead(item:AdminAnnouncement){readOpen.value=item;readRows.value=[];try{readRows.value=(await getAdminAnnouncementReadStatus(item.id,{page:1,page_size:20})).items}catch(caught){toast.error('阅读状态加载失败',{detail:errorMessage(caught,'请稍后重试。')})}}
function statusLabel(status:string){return status==='draft'?'草稿':status==='active'?'发布中':'已归档'}
onMounted(()=>void load())
</script>
<template><div class="page"><header class="page-header drag-region"><div><span>ANNOUNCEMENT CENTER</span><h1>公告管理</h1><p>编排站内通知、展示方式与目标受众。</p></div><button class="primary no-drag" data-testid="create-announcement" @click="openCreate"><MessageSquarePlus :size="17"/>新建公告</button></header><section class="summary"><div><Megaphone :size="18"/><span>公告总数</span><strong>{{total}}</strong></div><div><Send :size="18"/><span>发布中</span><strong>{{items.filter(i=>i.status==='active').length}}</strong></div><div><Edit3 :size="18"/><span>草稿</span><strong>{{items.filter(i=>i.status==='draft').length}}</strong></div></section><div class="toolbar"><select v-model="statusFilter" @change="load"><option value="">全部状态</option><option value="draft">草稿</option><option value="active">发布中</option><option value="archived">已归档</option></select></div><section v-if="loading" class="loading"><i v-for="n in 4" :key="n"/></section><section v-else-if="loadError" class="page-state" data-testid="announcement-error"><strong>公告列表加载失败</strong><span>{{loadError}}</span><button type="button" data-testid="retry-announcements" @click="load">重新加载</button></section><section v-else-if="!items.length" class="page-state" data-testid="announcement-empty"><strong>暂无公告</strong><span>新建公告后，可在这里管理发布状态和目标用户。</span><button type="button" @click="openCreate">新建公告</button></section><section v-else class="list"><article v-for="item in items" :key="item.id"><header><div class="mark" :class="item.status"><Megaphone :size="19"/></div><div class="title"><strong>{{item.title}}</strong><span>{{item.notify_mode==='popup'?'弹窗通知':'静默通知'}} · {{formatDateTime(item.updated_at)}}</span></div><em :class="item.status">{{statusLabel(item.status)}}</em></header><p>{{item.content}}</p><footer><span><Clock3 :size="13"/>{{item.starts_at?`开始 ${formatDateTime(item.starts_at)}`:'保存后按状态生效'}}</span><div><button :data-testid="`read-announcement-${item.id}`" title="阅读状态" @click="openRead(item)"><Eye :size="15"/></button><button title="编辑" @click="openEdit(item)"><Edit3 :size="15"/></button><button v-if="item.status==='draft'" :data-testid="`publish-announcement-${item.id}`" title="发布" :disabled="pending===`status-${item.id}`" @click="setStatus(item,'active')"><Send :size="15"/></button><button v-else-if="item.status==='active'" title="归档" :disabled="pending===`status-${item.id}`" @click="setStatus(item,'archived')"><Archive :size="15"/></button><button title="删除" :data-testid="`delete-announcement-${item.id}`" :disabled="pending===`delete-${item.id}`" @click="remove(item)"><Trash2 :size="15"/></button></div></footer></article></section>
<Transition name="fade"><div v-if="editorOpen" class="backdrop" @mousedown.self="editorOpen=false"><section class="editor"><header><div><h2>{{editing?'编辑公告':'新建公告'}}</h2><p>撰写内容并设置触达方式</p></div><button @click="editorOpen=false"><X :size="18"/></button></header><form data-testid="announcement-editor" @submit.prevent="save"><label class="wide"><span>标题</span><input v-model="form.title" data-testid="announcement-title"/></label><label class="wide"><span>内容</span><textarea v-model="form.content" data-testid="announcement-content" rows="7"/></label><label><span>状态</span><select v-model="form.status"><option value="draft">草稿</option><option value="active">直接发布</option><option value="archived">归档</option></select></label><label><span>通知方式</span><select v-model="form.notifyMode"><option value="silent">静默展示</option><option value="popup">登录弹窗</option></select></label><label><span>目标受众</span><select v-model="form.targetType"><option value="all">全部用户</option><option value="balance">按余额</option><option value="subscription">按订阅分组</option></select></label><label v-if="form.targetType==='balance'"><span>余额不低于</span><input v-model.number="form.balanceValue" type="number" min="0"/></label><label v-if="form.targetType==='subscription'" class="wide"><span>订阅分组 ID（逗号分隔）</span><input v-model="form.groupIds" placeholder="1, 2, 3"/></label><p v-if="editorError" class="form-error wide" data-testid="announcement-editor-error" role="alert">{{editorError}}</p><footer class="wide"><button type="button" @click="editorOpen=false">取消</button><button class="save" type="submit">保存公告</button></footer></form></section></div></Transition>
<Transition name="drawer"><div v-if="readOpen" class="drawer-backdrop" @mousedown.self="readOpen=null"><aside data-testid="announcement-read-status"><header><div><h2>{{readOpen.title}}</h2><p>目标用户与阅读状态</p></div><button @click="readOpen=null"><X :size="18"/></button></header><div class="read-summary"><div><span>目标用户</span><strong>{{readRows.filter(i=>i.eligible).length}}</strong></div><div><span>已阅读</span><strong>{{readRows.filter(i=>i.read_at).length}}</strong></div></div><div class="read-row head"><span>用户</span><span>余额</span><span>命中</span><span>阅读时间</span></div><div v-for="row in readRows" :key="row.user_id" class="read-row"><div><strong>{{row.username}}</strong><span>{{row.email}}</span></div><span>{{formatCost(row.balance)}}</span><em :class="{yes:row.eligible}">{{row.eligible?'是':'否'}}</em><span>{{formatDateTime(row.read_at)}}</span></div></aside></div></Transition></div></template>
<style scoped>.page{width:100%;min-height:100%;padding:28px 30px 34px;overflow:auto}.page-header{display:flex;align-items:flex-end;justify-content:space-between}.page-header>div>span{display:block;margin-bottom:5px;color:var(--accent);font-size:11px;font-weight:720;letter-spacing:.08em}.page-header h1{margin:0;font-size:25px}.page-header p{margin:7px 0 0;color:var(--text-secondary);font-size:14px}.primary{display:flex;height:36px;align-items:center;gap:7px;padding:0 13px;border:0;border-radius:7px;background:var(--accent);color:white}.summary{display:grid;grid-template-columns:repeat(3,1fr);margin-top:20px;background:white;border:1px solid var(--border-subtle);border-radius:8px}.summary>div{display:grid;min-height:64px;grid-template-columns:24px 1fr auto;align-items:center;gap:7px;padding:0 18px;border-right:1px solid var(--border-subtle)}.summary>div:last-child{border:0}.summary svg{color:var(--accent)}.summary span{color:var(--text-secondary);font-size:12px}.summary strong{font-family:var(--font-data);font-size:20px}.toolbar{display:flex;justify-content:flex-end;margin-top:12px}.toolbar select{height:36px;padding:0 9px;border:1px solid var(--border-subtle);border-radius:7px;background:white}.list{display:grid;grid-template-columns:repeat(2,1fr);gap:11px;margin-top:12px}.list article{display:flex;min-height:190px;flex-direction:column;padding:17px;background:rgba(255,255,255,.82);border:1px solid var(--border-subtle);border-radius:8px;box-shadow:0 6px 18px rgba(31,51,78,.04)}.list article>header{display:grid;grid-template-columns:38px minmax(0,1fr) auto;align-items:center;gap:9px}.mark{display:grid;width:36px;height:36px;background:#eef3fb;border-radius:8px;color:#59749e;place-items:center}.mark.active{background:#e9f1ff;color:#3c70c7}.title{display:grid;min-width:0;gap:4px}.title strong,.title span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.title span{color:var(--text-tertiary);font-size:10px}.list header em{padding:4px 7px;background:#eff2f5;border-radius:5px;color:#717c88;font-size:9px;font-style:normal}.list header em.active{background:#eaf8f1;color:#277a58}.list article>p{display:-webkit-box;margin:14px 0;color:var(--text-secondary);font-size:12px;line-height:1.65;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.list article>footer{display:flex;align-items:center;justify-content:space-between;margin-top:auto}.list footer>span{display:flex;align-items:center;gap:5px;color:var(--text-tertiary);font-size:9px}.list footer>div{display:flex;gap:4px}.list footer button{display:grid;width:28px;height:28px;border:0;border-radius:6px;background:var(--bg-base);color:var(--text-tertiary);place-items:center}.loading{display:grid;grid-template-columns:repeat(2,1fr);gap:11px;margin-top:12px}.loading i{height:190px;background:#edf1f5;border-radius:8px}.message{font-size:12px}.backdrop{position:fixed;z-index:100;inset:0;display:grid;background:rgba(28,39,56,.22);backdrop-filter:blur(10px);place-items:center}.editor{width:min(650px,calc(100% - 48px));max-height:calc(100vh - 48px);overflow:auto;background:white;border-radius:10px;box-shadow:0 25px 70px rgba(28,42,62,.24)}.editor>header,aside>header{display:flex;justify-content:space-between;padding:20px;border-bottom:1px solid var(--border-subtle)}.editor h2,aside h2{margin:0;font-size:18px}.editor header p,aside header p{margin:3px 0 0;color:var(--text-tertiary);font-size:11px}.editor header button,aside header button{border:0;background:transparent}.editor form{display:grid;grid-template-columns:repeat(2,1fr);gap:13px;padding:19px 20px}.wide{grid-column:1/-1}.editor label{display:grid;gap:5px}.editor label span{color:var(--text-secondary);font-size:11px}.editor input,.editor select,.editor textarea{padding:9px;border:1px solid var(--border-subtle);border-radius:7px;font:inherit;font-size:12px}.editor footer{display:flex;justify-content:flex-end;gap:8px}.editor footer button{height:36px;padding:0 13px;border:1px solid var(--border-subtle);border-radius:7px;background:white}.editor footer .save{background:var(--accent);color:white}.drawer-backdrop{position:fixed;z-index:90;inset:0;background:rgba(31,42,58,.16);backdrop-filter:blur(5px)}aside{position:absolute;top:0;right:0;width:min(560px,64vw);min-width:460px;height:100%;overflow:auto;background:#fafcff;box-shadow:-18px 0 54px rgba(32,47,68,.16)}.read-summary{display:grid;grid-template-columns:repeat(2,1fr);gap:9px;margin:16px 20px}.read-summary div{display:flex;align-items:center;justify-content:space-between;padding:12px;background:white;border:1px solid var(--border-subtle);border-radius:7px}.read-summary span{color:var(--text-secondary);font-size:11px}.read-summary strong{font-family:var(--font-data);font-size:18px}.read-row{display:grid;min-height:50px;grid-template-columns:1.4fr 70px 50px 105px;align-items:center;gap:8px;padding:0 20px;border-bottom:1px solid var(--border-subtle);font-size:10px}.read-row>div{display:grid;gap:3px}.read-row div span,.read-row>span{color:var(--text-tertiary)}.read-row em{font-style:normal;color:#a24b3d}.read-row em.yes{color:#267a58}.read-row.head{min-height:38px;background:#f4f7fa;color:var(--text-tertiary)}@container app-content (max-width:800px){.page{padding:24px}.list,.loading{grid-template-columns:1fr}}@container app-content (max-width:680px){.page-header{align-items:flex-start;flex-direction:column;gap:15px}.primary{width:100%;justify-content:center}.editor form{grid-template-columns:1fr}.editor form>*{grid-column:1}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}</style>
